import { dispatchMfeEvent } from '@ps-refarch-ux/mfe-utils';
/**
 * Shows the MFE in the SystemBanner area of the ApplicationShell.
 * @note: If your MFE is inside an application that is not using
 * the ApplicationShell then this function will not work.  That application
 * will need to implement its own API for adding and removing SystemBanners.
 * @param sourceMfe The id of the MFE that calls this function.
 * @param remote The remote of the MFE to show in the SystemBanner area.
 * @param url The url of the MFE to show in the SystemBanner area.
 * @param module The module of the MFE to show in the SystemBanner area.
 */
export function showSystemBanner(sourceMfe, remote, url, module) {
    dispatchMfeEvent(sourceMfe, 'application-shell.system-banner.show', {
        remote: remote,
        url: url,
        module: module
    });
}
/**
 * Hides the top MFE in the SystemBanner area of the ApplicationShell.
 * @note: If your MFE is inside an application that is not using
 * the ApplicationShell then this function will not work.  That application
 * will need to implement its own API for adding and removing SystemBanners.
 * @param sourceMfe The id of the MFE that calls this function.
 * @param remote The remote of the MFE to show in the SystemBanner area.
 * @param url The url of the MFE to show in the SystemBanner area.
 * @param module The module of the MFE to show in the SystemBanner area.
 */
export function hideTopSystemBanner(sourceMfe) {
    dispatchMfeEvent(sourceMfe, 'application-shell.system-banner.hide-top', {});
}
/**
 * Hides the MFE associated with the given information in the SystemBanner area of the ApplicationShell.
 * @note: If your MFE is inside an application that is not using
 * the ApplicationShell then this function will not work.  That application
 * will need to implement its own API for adding and removing SystemBanners.
 * @param sourceMfe The id of the MFE that calls this function.
 * @param remote The remote of the MFE to show in the SystemBanner area.
 * @param url The url of the MFE to show in the SystemBanner area.
 * @param module The module of the MFE to show in the SystemBanner area.
 */
export function hideSystemBanner(sourceMfe, remote, url, module) {
    dispatchMfeEvent(sourceMfe, 'application-shell.system-banner.hide', {
        remote: remote,
        url: url,
        module: module
    });
}
